using System.Security.AccessControl;
using System.Security.Principal;
using System.Text;
using FsAnalyser.App;

namespace FsAnalyser.Core.Tests;

/// <summary>
/// SC-028's probe against a folder that takes a new file but does not let this account delete or rename one in it (an inherited
/// Deny DELETE on its files and a Deny FILE_DELETE_CHILD on the folder, a create-only drop folder). The write's move needs DELETE on
/// the temporary, so the report cannot be put there; the probe has to say so up front, as it does for a folder that takes no file.
/// </summary>
public class ReportFileDropFolderTests
{
    [Fact]
    public void AProbeIsRefusedWhereTheWritesMoveWouldBeRefused()
    {
        using var tree = new TempTree();
        string folder = tree.Folder("drop");
        string report = Path.Combine(folder, "r.json");
        var directory = new DirectoryInfo(folder);
        SecurityIdentifier me = WindowsIdentity.GetCurrent().User!;
        var noDeleteChild = new FileSystemAccessRule(me, FileSystemRights.DeleteSubdirectoriesAndFiles,
            InheritanceFlags.None, PropagationFlags.None, AccessControlType.Deny);
        var noDeleteOfFiles = new FileSystemAccessRule(me, FileSystemRights.Delete,
            InheritanceFlags.ObjectInherit, PropagationFlags.InheritOnly, AccessControlType.Deny);
        DirectorySecurity security = directory.GetAccessControl();
        security.AddAccessRule(noDeleteChild);
        security.AddAccessRule(noDeleteOfFiles);
        directory.SetAccessControl(security);
        try
        {
            Exception? probe = Record.Exception(() => new ReportFile(report).Probe());
            Exception? write = Record.Exception(() => new ReportFile(report).Write(Encoding.UTF8.GetBytes("{ \"schema\": 1 }")));

            Assert.True(write is IOException or UnauthorizedAccessException,
                $"premise: the write's move must be refused in this folder, and it gave {write?.GetType().Name ?? "no exception"}");
            Assert.True(probe is IOException or UnauthorizedAccessException,
                "the probe passed a folder whose report the write then could not put in place, so the app would scan first and exit 3 only at the end");
        }
        finally
        {
            DirectorySecurity restored = directory.GetAccessControl();
            restored.RemoveAccessRule(noDeleteChild);
            restored.RemoveAccessRule(noDeleteOfFiles);
            directory.SetAccessControl(restored);
        }
    }
}

namespace FsAnalyser.Core.Tests;

// A root typed with an unpaired backslash-quote and no opening quote: Windows splits the line into three arguments, and only
// the root carries a trailing quote, which RootArgument repairs. The repair must not join what Windows split.
public class CommandLineUnpairedQuoteTests
{
    [Fact]
    public void AnUnpairedQuoteAfterABackslashDoesNotJoinWhatWindowsSplit()
    {
        const string tail = @"D:\Data\"" --report out.json";
        string[] argv = TestNative.SplitArguments(tail);
        Assert.Equal([@"D:\Data""", "--report", "out.json"], argv);

        string[]? got = CommandLine.Arguments(argv, "app.exe " + tail);

        Assert.NotNull(got);
        Assert.Equal(3, got.Length);
        Assert.Equal(@"D:\Data\", CommandLine.RootArgument(got[0]));
        Assert.Equal("--report", got[1]);
        Assert.Equal("out.json", got[2]);
    }
}

using System.Text.RegularExpressions;

namespace FsAnalyser.Core.Tests;

// Spellings of StartupEventArgs.Args read before CommandLine.Arguments that the settled SL-007 rule must catch.
public class SettledArgsRuleMissedSpellingTests
{
    private static string[] Patterns(string name)
    {
        string[] lines = File.ReadAllLines(Path.Combine(FailCriticalErrorsTests.FindRepo(), ".taad", "fitness.yaml"));
        int at = Array.FindIndex(lines, l => l.Trim() == "- name: " + name);
        Assert.True(at >= 0, name);
        var patterns = new List<string>();
        bool inPatterns = false;
        for (int i = at + 1; i < lines.Length && !lines[i].StartsWith("  - name:", StringComparison.Ordinal) && !lines[i].StartsWith("  #", StringComparison.Ordinal); i++)
        {
            string t = lines[i].Trim();
            if (lines[i].StartsWith("    ", StringComparison.Ordinal) && !lines[i].StartsWith("     ", StringComparison.Ordinal) && !t.StartsWith("- ", StringComparison.Ordinal))
                inPatterns = t.StartsWith("must_not_match:", StringComparison.Ordinal);
            else if (inPatterns && t.StartsWith("- '", StringComparison.Ordinal) && t.EndsWith('\''))
                patterns.Add(t[3..^1].Replace("''", "'"));
        }
        Assert.NotEmpty(patterns);
        return [.. patterns];
    }

    [Theory]
    [InlineData("        if (e?.Args.Contains(ReportOption) == true)")]
    [InlineData("        string[] a = e!.Args;")]
    [InlineData("        string[] a = (e).Args;")]
    public void TheArgsRuleCatchesTheProperty(string line)
    {
        string[] patterns = Patterns("the app decides its mode only on repaired arguments");
        Assert.True(patterns.Any(p => Regex.IsMatch(line, p)), line);
    }
}

findings.claim:
The settled rule 'the app writes files only by exclusive create' lets three BCL writers through that write through an entry already at the name. Its because text says 'Every byte the App writes goes through ReportFile', and these break that:
- `File.AppendAllBytes` / `AppendAllBytesAsync`, a .NET 9+ API that `AppendAll(Text|Lines)` misses;
- `File.Copy(src, dst, overwrite: true)` and `FileInfo.CopyTo(dst, true)`;
- `FileInfo.Open(mode, ...)` with the mode in a variable, the same shape as row C16 for File.Open.

File.Copy is the obvious alternative to the File.Move that ReportFile uses to put the temporary over <report>, the one predictable name. Measured here: File.Copy(src, r.json, true) with a hardlink at r.json overwrote the sentinel's bytes. With a file symlink at the destination it overwrote the symlink's target. That is SC-037 at the fixed name, with the rule still green.

The build declared this family closed (O-024, SettledRulesCorpus.json); these are new members.

